/// <summary>
/// PricingAttribute of table <c>CustTable</c> field MainContactWorker.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, MainContactWorker))]
internal class GUPPricingAttributeCustTableMainContactWorker extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{

}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, MainContactWorker);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Int64);
    CustTable   custTable;

    while select MainContactWorker from custTable
        group by MainContactWorker
    {
        ret.add(custTable.MainContactWorker);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, MainContactWorker));
    qbr.value(queryValue(_value));
}

public str getRefValue(Str _defaultValue)
{
    HcmWorker hcmWorker;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(HcmWorker)).addRange(fieldNum(HcmWorker, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        hcmWorker = qr.get(tableNum(HcmWorker), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += hcmWorker.name();
    }

    return ret;
}

public void lookupAllowedValues(object _formStringControl)
{

    HcmWorkerLookup hcmWorkerLookup = HcmWorkerLookup::newOnlyActiveEmployeesWithinCompany();
    hcmWorkerLookup.parmreturnRefRecID(true);
    Query query = hcmWorkerLookup.updateQuery();

    CustTable   custTable;
    while select MainContactWorker from custTable
        group by MainContactWorker
    {
        query.dataSourceName(tableStr(HcmWorker)).addRange(fieldNum(HcmWorker, RecId)).value(int642Str(custTable.MainContactWorker));
    }

    hcmWorkerLookup.lookupWorker(_formStringControl);


}
